CREATE TABLE IF NOT EXISTS warehouse_return_items (id INTEGER PRIMARY KEY AUTOINCREMENT, source TEXT NOT NULL, cycle_key TEXT NOT NULL, order_id TEXT NOT NULL, order_name TEXT, machine TEXT, line_item_id TEXT NOT NULL, variant_id TEXT, sku TEXT, barcode TEXT, title TEXT, unit_index INTEGER NOT NULL, status TEXT NOT NULL, created_at TEXT NOT NULL, created_by TEXT, received_at TEXT, received_by TEXT, receive_mode TEXT, UNIQUE (source, order_id, cycle_key, line_item_id, unit_index)); CREATE INDEX IF NOT EXISTS idx_wri_status ON warehouse_return_items (status, source, created_at); CREATE INDEX IF NOT EXISTS idx_wri_barcode ON warehouse_return_items (barcode, status, created_at); CREATE INDEX IF NOT EXISTS idx_wri_order ON warehouse_return_items (order_id);
